export const localeInfo = {
  'pt-br': { lang: 'pt-BR', locale: 'pt-BR', label: 'Português' },
  en: { lang: 'en', locale: 'en-US', label: 'English' },
  es: { lang: 'es', locale: 'es-ES', label: 'Español' },
};

export const messages = Object.fromEntries(
  Object.keys(localeInfo).map((locale, index) => [
    locale,
    Object.fromEntries(Object.entries(copy).map(([key, values]) => [key, values[index]])),
  ]),
);

export function translate(locale, key, vars = {}) {
  const value = messages[locale]?.[key] ?? messages['pt-br'][key] ?? key;
  return value.replace(/\{([a-zA-Z0-9_]+)\}/g, (placeholder, name) =>
    Object.prototype.hasOwnProperty.call(vars, name) ? String(vars[name]) : placeholder,
  );
}
